$sourceFiles+=@(Get-ChildItem (Join-Path $repo 'native\providers\moe_accumulator') -Filter '*.h' -File|ForEach-Object {$_.FullName})
$sourceInputs=@();foreach($name in $sourceFiles){$file=if([IO.Path]::IsPathRooted($name)){$name}else{Join-Path $repo $name};$sourceInputs+=@{file=$file;sha256=(Get-FileHash $file -Algorithm SHA256).Hash.ToLowerInvariant()}}
$spec=[ordered]@{executable='';arguments=@();working_directory=$repo;repo_commit=$sha;command_file=$PSCommandPath;command_file_sha256=(Get-FileHash $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();source_inputs=$sourceInputs;sm121_dpp_reduction=$true;sm121_compact_normalize=$true;hawkeye_replay_lanes=4;prefill_hipblaslt_producer=$true;hawkeye_device_replay=$false;hawkeye_prepared_operands=$true;hawkeye_absolute_product_bound=$false;hawkeye_prepared_k16_major=$true;hawkeye_absolute_product_hipblaslt=$true;matrix_window_timeout_ms=250;exact_dispatch_timeout_ms=100;aggregate_correction_timeout_ms=10000;maximum_blocks_per_launch=4096;model='none; native build or original-vs-device-count correction test';model_loaded=$false;inference_acceptance=$false;purpose='Validate a lossless K16-major prepared-operand permutation with identical products, ordered carry, candidate admission and raw-row fallback. Model continuation and retained performance require separate real q8192 measurements.'}
if($Action -like '*-build'){
